import ProductCard from "../components/ProductCard";

function Home() {
  return (
    <div>
      <h2>Bienvenido a TiendaClick</h2>

      <ProductCard nombre="Arroz" precio="5.00" />

      <ProductCard nombre="Aceite" precio="12.00" />

      <ProductCard nombre="Azúcar" precio="4.50" />
    </div>
  );
}

export default Home;
